/* Backlog Studio — aplicativo estático, sem serviços externos e sem dependências. */
(() => {
  'use strict';
  const DB_NAME = 'backlog-studio-v1';
  const STORE = 'workspace';
  const LS_DATA = 'backlog-studio-fallback-data';
  const LS_PREFS = 'backlog-studio-preferences';
  const CHANNEL = 'backlog-studio-sync';
  const STATUSES = { backlog:'Backlog', todo:'A fazer', doing:'Em andamento', review:'Em revisão', done:'Concluído' };
  const PRIORITIES = { urgent:'Crítica', high:'Alta', medium:'Média', low:'Baixa' };
  const TYPES = { feature:'Funcionalidade', task:'Tarefa', bug:'Bug', improvement:'Melhoria', research:'Pesquisa' };
  const COLORS = { backlog:'#91a0b6', todo:'#6186d8', doing:'#3b78e7', review:'#e9a348', done:'#25aa7b' };
  const PRIORITY_ORDER = {urgent:0,high:1,medium:2,low:3};
  const $ = (selector, root=document) => root.querySelector(selector);
  const $$ = (selector, root=document) => Array.from(root.querySelectorAll(selector));
  const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const uid = () => (globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`);
  const now = () => new Date().toISOString();
  const today = () => { const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
  const datePt = value => { if(!/^\d{4}-\d{2}-\d{2}$/.test(value||'')) return 'Sem prazo'; const [y,m,d]=value.split('-'); return `${d}/${m}/${y}`; };
  const dateTime = value => { const d=new Date(value); return isNaN(d) ? 'Data desconhecida' : d.toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}); };
  const relative = value => { const diff=Math.max(0,Date.now()-new Date(value).getTime()); if(!Number.isFinite(diff))return dateTime(value); if(diff<60000)return 'Agora'; if(diff<3600000)return `Há ${Math.floor(diff/60000)} min`; if(diff<86400000)return `Há ${Math.floor(diff/3600000)} h`; if(diff<604800000)return `Há ${Math.floor(diff/86400000)} dias`; return dateTime(value); };
  const overdue = item => Boolean(item.dueDate && item.dueDate < today() && item.status!=='done' && !item.archived);
  const clampNum = value => Math.min(100000, Math.max(0, Number(value)||0));
  const urlSafe = value => {try{const url=new URL(value);return ['https:','http:'].includes(url.protocol)?url.href:'';}catch{return '';}};
  const textLines = value => esc(value).replace(/\n/g,'<br>');
  const fieldNames = {title:'Título',description:'Descrição',type:'Tipo',priority:'Prioridade',status:'Situação',projectId:'Projeto',assignee:'Responsável',startDate:'Data de início',dueDate:'Prazo',estimate:'Estimativa',spent:'Horas gastas',sprint:'Sprint',labels:'Etiquetas',link:'Referência'};
  const defaultData = () => ({version:1,revision:now(),projects:[],items:[],activities:[],lastBackupAt:null});
  const defaultPrefs = {view:'dashboard',projectId:'all',theme:'light',priority:'all',type:'all',status:'all',sort:'updated',search:'',showArchived:false,calendarOffset:0};
  let state=defaultData(), prefs={...defaultPrefs}, db=null, storageMode='idb', channel=null, saveQueue=Promise.resolve(), currentItemId=null, currentProjectId=null, resolveConfirm=null, isSaving=false;
  let showErrorCounter=0;

  function normalizeState(obj){
    if(!obj || typeof obj!=='object'||Array.isArray(obj)||obj.version!==1||!Array.isArray(obj.projects)||!Array.isArray(obj.items)||!Array.isArray(obj.activities)) throw new Error('Arquivo não reconhecido como backup válido do Backlog Studio (versão 1).');
    const unique = arr => new Set(arr.map(x=>x.id)).size===arr.length;
    if(!unique(obj.projects)||!unique(obj.items)||!unique(obj.activities)) throw new Error('Backup contém identificadores duplicados.');
    const projects=obj.projects.map(p=>({id:String(p.id),name:String(p.name||'Sem nome').slice(0,85),key:String(p.key||'PRJ').slice(0,8),color:/^#[0-9a-fA-F]{6}$/.test(p.color)?p.color:'#2563eb',description:String(p.description||'').slice(0,3000),repository:urlSafe(p.repository||''),archived:Boolean(p.archived),createdAt:p.createdAt||now(),updatedAt:p.updatedAt||now()}));
    const pIds=new Set(projects.map(p=>p.id));
    const items=obj.items.map(i=>({id:String(i.id),projectId:String(i.projectId),number:Math.max(1,Number(i.number)||1),title:String(i.title||'Sem título').slice(0,200),description:String(i.description||'').slice(0,20000),type:TYPES[i.type]?i.type:'task',priority:PRIORITIES[i.priority]?i.priority:'medium',status:STATUSES[i.status]?i.status:'backlog',assignee:String(i.assignee||'').slice(0,80),startDate:/^\d{4}-\d{2}-\d{2}$/.test(i.startDate)?i.startDate:'',dueDate:/^\d{4}-\d{2}-\d{2}$/.test(i.dueDate)?i.dueDate:'',estimate:clampNum(i.estimate),spent:clampNum(i.spent),sprint:String(i.sprint||'').slice(0,80),labels:Array.isArray(i.labels)?i.labels.map(s=>String(s).slice(0,40)).slice(0,20):[],link:urlSafe(i.link||''),checklist:Array.isArray(i.checklist)?i.checklist.map(c=>({id:String(c.id||uid()),text:String(c.text||'').slice(0,500),done:Boolean(c.done)})):[],comments:Array.isArray(i.comments)?i.comments.map(c=>({id:String(c.id||uid()),text:String(c.text||'').slice(0,5000),createdAt:c.createdAt||now()})):[],archived:Boolean(i.archived),createdAt:i.createdAt||now(),updatedAt:i.updatedAt||now(),completedAt:i.completedAt||null}));
    if(items.some(i=>!pIds.has(i.projectId))) throw new Error('Backup contém itens vinculados a projetos inexistentes.');
    const activities=obj.activities.map(a=>({id:String(a.id),time:a.time||now(),projectId:a.projectId||null,itemId:a.itemId||null,kind:String(a.kind||'update').slice(0,40),text:String(a.text||'Atividade').slice(0,900),details:Array.isArray(a.details)?a.details.map(d=>({field:String(d.field||''),before:String(d.before??'').slice(0,500),after:String(d.after??'').slice(0,500)})):[]}));
    return {version:1,revision:obj.revision||now(),projects,items,activities,lastBackupAt:obj.lastBackupAt||null};
  }
  function openDb(){return new Promise((resolve,reject)=>{const request=indexedDB.open(DB_NAME,1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains(STORE))request.result.createObjectStore(STORE);};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);request.onblocked=()=>reject(new Error('Banco bloqueado por outra aba.'));});}
  function getFromIdb(){return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readonly');const request=tx.objectStore(STORE).get('state');request.onsuccess=()=>resolve(request.result||null);request.onerror=()=>reject(request.error);});}
  function putToIdb(snapshot){return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put(snapshot,'state');tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error||new Error('Falha de escrita'));tx.onabort=()=>reject(tx.error||new Error('Escrita interrompida'));});}
  function updateSaveStatus(text,status){const el=$('#saveStatus');el.className=`save-status ${status||''}`;el.innerHTML=`<span class="status-dot"></span> ${esc(text)}`;}
  function save(){
    state.revision=uid();const snapshot=structuredClone(state);isSaving=true;updateSaveStatus('Salvando...','saving');
    saveQueue=saveQueue.catch(()=>{}).then(async()=>{
      try { if(storageMode==='idb') await putToIdb(snapshot); else localStorage.setItem(LS_DATA,JSON.stringify(snapshot));
        if(channel) channel.postMessage({revision:snapshot.revision});
        else localStorage.setItem('backlog-studio-ping',snapshot.revision);
        if(snapshot.revision===state.revision)updateSaveStatus('Salvo localmente','');
      }catch(error){updateSaveStatus('Erro ao salvar!','error');toast('Erro ao salvar dados: '+error.message+'. Exporte um backup agora.','error');}
      finally {if(snapshot.revision===state.revision)isSaving=false;}
    });
    return saveQueue;
  }
  function savePrefs(){try{localStorage.setItem(LS_PREFS,JSON.stringify({...prefs,search:''}));}catch{}}
  function activity(kind,text,projectId=null,itemId=null,details=[]){state.activities.unshift({id:uid(),kind,time:now(),text,projectId,itemId,details});}
  function change(fn){fn();render();return save();}
  function findProject(id){return state.projects.find(p=>p.id===id);}
  function findItem(id){return state.items.find(i=>i.id===id);}
  function keyOf(item){return `${findProject(item.projectId)?.key||'PRJ'}-${item.number}`;}
  function projectVisible(id){const p=findProject(id);return p && !p.archived;}
  function scopeItems(includeArchived=false){return state.items.filter(i=>(prefs.projectId==='all'||i.projectId===prefs.projectId)&&(includeArchived||(!i.archived&&projectVisible(i.projectId))));}
  function filteredItems(){const query=prefs.search.trim().toLocaleLowerCase('pt-BR');return scopeItems(prefs.showArchived).filter(i=>(prefs.priority==='all'||i.priority===prefs.priority)&&(prefs.type==='all'||i.type===prefs.type)&&(prefs.status==='all'||i.status===prefs.status)&&(!query||[i.title,i.description,keyOf(i),i.assignee,i.sprint,...i.labels,findProject(i.projectId)?.name||''].join(' ').toLocaleLowerCase('pt-BR').includes(query))).sort((a,b)=>{
    if(prefs.sort==='priority')return (PRIORITY_ORDER[a.priority]-PRIORITY_ORDER[b.priority])||b.updatedAt.localeCompare(a.updatedAt);
    if(prefs.sort==='due')return (a.dueDate||'9999').localeCompare(b.dueDate||'9999');
    if(prefs.sort==='created')return b.createdAt.localeCompare(a.createdAt);
    if(prefs.sort==='title')return a.title.localeCompare(b.title,'pt-BR');
    return b.updatedAt.localeCompare(a.updatedAt);
  });}
  function projectCounts(p){const items=state.items.filter(i=>i.projectId===p.id&&!i.archived);return {count:items.length,done:items.filter(i=>i.status==='done').length};}
  function statusBadge(s){return `<span class="status-badge ${esc(s)}">${esc(STATUSES[s]||s)}</span>`;}
  function priorityBadge(p){return `<span class="priority-badge ${esc(p)}"><i class="priority-dot"></i>${esc(PRIORITIES[p]||p)}</span>`;}
  function typeSymbol(type){const glyph={feature:'✦',task:'✓',bug:'!',improvement:'↗',research:'⌕'}[type]||'•';return `<span class="type-symbol ${esc(type)}" title="${esc(TYPES[type])}">${glyph}</span>`;}
  function projectOptions(selected){return `<option value="all" ${selected==='all'?'selected':''}>Todos os projetos</option>`+state.projects.filter(p=>!p.archived).map(p=>`<option value="${esc(p.id)}" ${selected===p.id?'selected':''}>${esc(p.name)}</option>`).join('');}
  function render(){
    if(prefs.projectId!=='all'&&!projectVisible(prefs.projectId)){prefs.projectId='all';savePrefs();}
    $$('.nav-item[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===prefs.view));
    $('#projectNav').innerHTML=state.projects.filter(p=>!p.archived).map(p=>`<button class="project-link ${prefs.projectId===p.id?'active':''}" data-action="select-project" data-id="${esc(p.id)}"><span class="project-dot" style="background:${p.color}"></span><span class="name">${esc(p.name)}</span><span class="project-count">${projectCounts(p).count}</span></button>`).join('')||'<div class="mini-description" style="padding:9px 13px">Nenhum projeto ainda.</div>';
    const pages={dashboard:renderDashboard,board:renderBoard,list:renderList,calendar:renderCalendar,activity:renderActivity,settings:renderSettings};
    const titles={dashboard:'Visão geral',board:'Quadro Kanban',list:'Backlog completo',calendar:'Calendário',activity:'Histórico',settings:'Configurações'};
    $('#breadcrumbView').textContent=titles[prefs.view]||titles.dashboard;
    $('#themeToggle').textContent=prefs.theme==='dark'?'☀':'☾';
    $('#app').dataset.theme=prefs.theme;
    $('#main').innerHTML=(pages[prefs.view]||pages.dashboard)();
  }
  function pageHead(title,desc,options={}){return `<div class="page-header"><div><div class="eyebrow">${esc(options.eyebrow||'CONTROLE DE PROJETOS')}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><div class="page-actions">${options.editProject&&prefs.projectId!=='all'?`<button class="btn btn-ghost" data-action="edit-project" data-id="${esc(prefs.projectId)}">⚙ Editar projeto</button>`:''}<button class="btn btn-ghost" data-action="new-project">＋ Projeto</button><button class="btn btn-primary" data-action="new-item" ${!state.projects.some(p=>!p.archived)?'disabled':''}>＋ Novo item</button></div></div>`;}
  function empty(title,desc,buttonText='Criar projeto',action='new-project'){return `<div class="empty-state"><div class="empty-icon">▦</div><h3>${esc(title)}</h3><p>${esc(desc)}</p><button class="btn btn-primary" data-action="${esc(action)}">＋ ${esc(buttonText)}</button></div>`;}
  function backupWarning(){if(!state.items.length)return '';if(state.lastBackupAt && (Date.now()-new Date(state.lastBackupAt).getTime())<7*86400000)return '';return `<div class="warning-banner">⚠ <strong>Proteja seus dados:</strong> suas informações estão neste navegador, não no GitHub. ${state.lastBackupAt?'Seu último backup tem mais de 7 dias.':'Você ainda não exportou um backup.'} <button class="small-link" data-action="backup-json">Exportar agora</button></div>`;}
  function renderDashboard(){
    let all=scopeItems(),active=all.filter(i=>i.status!=='done'),done=all.filter(i=>i.status==='done').length,doing=all.filter(i=>i.status==='doing').length,late=all.filter(overdue).length;
    const hdr=pageHead(prefs.projectId==='all'?'Visão geral dos projetos':findProject(prefs.projectId)?.name||'Visão geral','Acompanhe o andamento, as entregas e as próximas prioridades.',{editProject:true});
    if(!state.projects.some(p=>!p.archived))return hdr+empty('Seu espaço de trabalho está pronto','Crie seu primeiro projeto para organizar tarefas, registrar decisões e acompanhar cada etapa do desenvolvimento.');
    let stats=`<div class="stats-grid">${metric('Itens em aberto',active.length,'☷','',`${all.length} itens cadastrados`)}${metric('Em andamento',doing,'↗','orange','Atividades em execução')}${metric('Concluídos',done,'✓','green',all.length?`${Math.round(done/all.length*100)}% de conclusão`:'Sem entregas ainda')}${metric('Atrasados',late,'!','purple','Itens com prazo vencido')}</div>`;
    const projects=state.projects.filter(p=>!p.archived&&(prefs.projectId==='all'||p.id===prefs.projectId));
    const pCards=`<div class="section-title-row"><h2>Projetos ativos</h2><span class="subheading">${projects.length} ${projects.length===1?'projeto':'projetos'}</span></div><div class="projects-grid">${projects.map(projectCard).join('')}</div>`;
    const byStatus=Object.keys(STATUSES).map(k=>({key:k,num:all.filter(i=>i.status===k).length}));const total=all.length;let pos=0;
    const gradient=total?`conic-gradient(${byStatus.map(e=>{const a=pos;pos+=e.num/total*100;return `${COLORS[e.key]} ${a}% ${pos}%`;}).join(',')})`:'conic-gradient(var(--line) 0% 100%)';
    const chart=`<section class="panel"><div class="section-title-row"><h2>Distribuição do backlog</h2></div><div class="donut-layout"><div class="donut" style="background:${gradient}"><div class="donut-inner"><strong>${total}</strong><small>Itens no total</small></div></div><div class="legend">${byStatus.map(e=>`<div class="legend-line"><span class="legend-dot" style="background:${COLORS[e.key]}"></span>${esc(STATUSES[e.key])}<b>${e.num}</b></div>`).join('')}</div></div></section>`;
    const last=state.activities.filter(a=>prefs.projectId==='all'||a.projectId===prefs.projectId).slice(0,6);
    const activityPanel=`<section class="panel"><div class="section-title-row"><h2>Atividade recente</h2><button class="small-link" data-action="navigate" data-view="activity">Ver histórico</button></div>${last.length?last.map(activityRow).join(''):'<p class="empty-inline">As mudanças dos seus projetos aparecerão aqui.</p>'}</section>`;
    const latest=active.sort((a,b)=>PRIORITY_ORDER[a.priority]-PRIORITY_ORDER[b.priority]||(a.dueDate||'9999').localeCompare(b.dueDate||'9999')).slice(0,6);
    const taskPanel=`<section class="panel"><div class="section-title-row"><h2>Próximas prioridades</h2><button class="small-link" data-action="navigate" data-view="list">Ver backlog</button></div><div class="recent-tasks">${latest.length?latest.map(i=>`<div class="task-line">${typeSymbol(i.type)}<div class="task-main"><strong data-action="edit-item" data-id="${esc(i.id)}">${esc(i.title)}</strong><small>${esc(keyOf(i))} · ${esc(findProject(i.projectId)?.name||'')}</small></div>${priorityBadge(i.priority)}</div>`).join(''):'<p class="empty-inline">Nenhuma pendência. Cadastre um item do backlog.</p>'}</div></section>`;
    return hdr+backupWarning()+stats+pCards+`<div class="two-col">${taskPanel}${chart}</div>`+activityPanel;
  }
  function metric(name,value,icon,variant,foot){return `<section class="metric"><div class="metric-top"><span>${name}</span><span class="metric-icon ${variant}">${icon}</span></div><div class="metric-number">${value}</div><div class="metric-foot">${foot}</div></section>`;}
  function projectCard(p){const x=projectCounts(p),progress=x.count?Math.round(x.done/x.count*100):0;return `<div class="project-card" data-action="select-project" data-id="${esc(p.id)}" role="button" tabindex="0"><div class="project-card-head"><div class="project-square" style="background:${p.color}">${esc(p.key.slice(0,2))}</div><span class="mini-pill">${x.count} itens</span></div><h3>${esc(p.name)}</h3><p>${esc(p.description||'Organize o trabalho e acompanhe o desenvolvimento.')}</p><div class="project-meta"><span>Progresso de entregas</span><strong>${progress}%</strong></div><div class="progress-track"><span style="width:${progress}%"></span></div></div>`;}
  function filterBar(){return `<div class="toolbar"><div class="search-wrap"><span>⌕</span><input id="searchInput" aria-label="Buscar itens" placeholder="Buscar tarefas, códigos, tags... (Ctrl+K)" value="${esc(prefs.search)}"></div><select id="projectFilter" class="filter-select" aria-label="Filtrar projeto">${projectOptions(prefs.projectId)}</select><select id="priorityFilter" class="filter-select" aria-label="Filtrar prioridade"><option value="all">Todas prioridades</option>${Object.keys(PRIORITIES).map(v=>`<option value="${v}" ${prefs.priority===v?'selected':''}>${PRIORITIES[v]}</option>`).join('')}</select><select id="typeFilter" class="filter-select" aria-label="Filtrar tipo"><option value="all">Todos tipos</option>${Object.keys(TYPES).map(v=>`<option value="${v}" ${prefs.type===v?'selected':''}>${TYPES[v]}</option>`).join('')}</select></div>`;}
  function renderBoard(){let list=filteredItems();return pageHead('Quadro Kanban','Arraste os cartões entre as etapas para atualizar o andamento.')+backupWarning()+filterBar()+`<div class="section-title-row"><span class="filter-count">${list.length} ${list.length===1?'item encontrado':'itens encontrados'}</span><span class="shortcut">Dica: clique no cartão para editar · Arraste para mudar status</span></div><div class="board">${Object.keys(STATUSES).map(s=>`<div class="board-column" data-drop-status="${s}"><div class="column-header"><strong><i class="column-dot" style="background:${COLORS[s]}"></i>${STATUSES[s]}</strong><span>${list.filter(i=>i.status===s).length}</span></div>${list.filter(i=>i.status===s).map(boardCard).join('')||'<div class="board-empty">Arraste itens para cá</div>'}</div>`).join('')}</div>`;}
  function boardCard(i){const p=findProject(i.projectId);return `<article class="board-card" draggable="true" data-drag-id="${esc(i.id)}" data-action="edit-item" data-id="${esc(i.id)}" tabindex="0"><div class="card-top"><span class="task-id">${esc(keyOf(i))}</span>${priorityBadge(i.priority)}</div><div class="card-title">${esc(i.title)}</div>${i.labels.length?`<div class="tag-wrap">${i.labels.slice(0,3).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>`:''}<div class="card-bottom"><span class="project-small"><i class="project-dot" style="background:${p?.color||'#2563eb'}"></i>${esc(p?.name||'')}</span><span class="due ${overdue(i)?'overdue':''}">${i.dueDate?'◷ '+datePt(i.dueDate):'Sem prazo'}</span></div></article>`;}
  function renderList(){const list=filteredItems();return pageHead('Backlog completo','Gerencie todos os requisitos, bugs, melhorias e tarefas num só lugar.')+backupWarning()+filterBar()+`<div class="toolbar"><select id="statusFilter" class="filter-select"><option value="all">Todos status</option>${Object.keys(STATUSES).map(k=>`<option value="${k}" ${prefs.status===k?'selected':''}>${STATUSES[k]}</option>`).join('')}</select><select id="sortFilter" class="filter-select"><option value="updated" ${prefs.sort==='updated'?'selected':''}>Atualizados recentemente</option><option value="priority" ${prefs.sort==='priority'?'selected':''}>Maior prioridade</option><option value="due" ${prefs.sort==='due'?'selected':''}>Prazo mais próximo</option><option value="created" ${prefs.sort==='created'?'selected':''}>Criados recentemente</option><option value="title" ${prefs.sort==='title'?'selected':''}>Ordem alfabética</option></select><label class="mini-description"><input type="checkbox" id="showArchived" ${prefs.showArchived?'checked':''}> Incluir arquivados</label><span class="filter-count">${list.length} itens</span></div>${list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Código</th><th>Item</th><th>Projeto</th><th>Prioridade</th><th>Status</th><th>Prazo</th><th>Horas</th><th>Atualizado</th></tr></thead><tbody>${list.map(i=>`<tr><td class="muted"><b>${esc(keyOf(i))}</b></td><td class="item-title-cell"><button class="item-title-button" data-action="edit-item" data-id="${esc(i.id)}">${esc(i.title)}</button><div class="table-subtitle">${esc(TYPES[i.type])}${i.archived?' · ARQUIVADO':''}${i.sprint?' · '+esc(i.sprint):''}</div></td><td>${esc(findProject(i.projectId)?.name||'')}</td><td>${priorityBadge(i.priority)}</td><td>${statusBadge(i.status)}</td><td class="${overdue(i)?'warning-note':'muted'}">${datePt(i.dueDate)}</td><td class="muted">${i.spent||0} / ${i.estimate||0}</td><td class="muted">${relative(i.updatedAt)}</td></tr>`).join('')}</tbody></table><div class="table-footer">${list.length} registros · Clique em um título para consultar e editar.</div></div>`:empty('Nenhum item encontrado','Mude os filtros ou cadastre o primeiro item do backlog.','Criar item','new-item')}`;}
  function renderCalendar(){const date=new Date();date.setDate(1);date.setMonth(date.getMonth()+prefs.calendarOffset);const year=date.getFullYear(),month=date.getMonth();const first=new Date(year,month,1);const startOffset=(first.getDay()+6)%7;const totalDays=new Date(year,month+1,0).getDate();const days=Math.ceil((startOffset+totalDays)/7)*7;const all=filteredItems().filter(i=>i.dueDate);let cells='';for(let d=0;d<days;d++){const day=new Date(year,month,1-startOffset+d);const key=`${day.getFullYear()}-${String(day.getMonth()+1).padStart(2,'0')}-${String(day.getDate()).padStart(2,'0')}`;const list=all.filter(i=>i.dueDate===key);cells+=`<div class="calendar-day ${day.getMonth()!==month?'other-month':''} ${key===today()?'today':''}"><div class="calendar-date">${day.getDate()}</div>${list.slice(0,3).map(i=>`<div class="calendar-event ${i.status==='done'?'done':''}" data-action="edit-item" data-id="${esc(i.id)}" title="${esc(i.title)}">${esc(i.title)}</div>`).join('')}${list.length>3?`<span class="calendar-more">+${list.length-3} itens</span>`:''}</div>`;}
    return pageHead('Calendário de entregas','Visualize tarefas, marcos e prazos de todos os projetos.')+filterBar()+`<div class="month-nav"><button class="btn btn-ghost" data-action="month-prev">‹</button><strong>${date.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</strong><button class="btn btn-ghost" data-action="month-next">›</button><button class="btn btn-ghost" data-action="month-today">Hoje</button><span class="mini-description">${all.length} itens com prazo</span></div><div class="calendar-grid">${['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(d=>`<div class="calendar-weekday">${d}</div>`).join('')}${cells}</div>`;
  }
  function activityRow(a){const icon={item_create:'＋',item_edit:'✎',status:'↗',comment:'☷',checklist:'✓',item_archive:'▣',project_create:'▦',project_edit:'⚙',project_archive:'▣',import:'⇧'}[a.kind]||'◷';const proj=findProject(a.projectId);return `<div class="activity-row"><span class="activity-marker">${icon}</span><div class="activity-content"><strong>${esc(a.text)}</strong><p>${proj?esc(proj.name)+' · ':''}${(a.details||[]).slice(0,3).map(d=>`${esc(d.field)}: ${esc(d.before)} → ${esc(d.after)}`).join(' · ')}</p></div><span class="activity-time" title="${esc(dateTime(a.time))}">${esc(relative(a.time))}</span></div>`;}
  function renderActivity(){const events=state.activities.filter(a=>prefs.projectId==='all'||a.projectId===prefs.projectId);return pageHead('Histórico de atividades','Trilha cronológica das mudanças, decisões e entregas registradas.')+`<div class="toolbar"><select id="projectFilter" class="filter-select" aria-label="Filtrar projeto">${projectOptions(prefs.projectId)}</select><span class="filter-count">${events.length} eventos registrados · Mais recentes primeiro</span></div><div class="panel activity-feed">${events.length?events.map(activityRow).join(''):empty('Histórico ainda vazio','O sistema registra automaticamente criação, alterações, mudanças de etapa e comentários.')}</div>`;}
  function renderSettings(){const active=state.projects.filter(p=>!p.archived).length,archived=state.projects.filter(p=>p.archived);return pageHead('Configurações e segurança','Gerencie os backups e o armazenamento do seu espaço de trabalho.',{eyebrow:'PREFERÊNCIAS'})+backupWarning()+`<div class="settings-grid"><section class="settings-card"><h3>Backup completo em JSON</h3><p>Salva projetos, backlog, comentários, checklists e TODO o histórico em um arquivo. Mantenha cópias fora do navegador para não perder dados.</p><div class="settings-actions"><button class="btn btn-primary" data-action="backup-json">⇩ Exportar backup JSON</button><button class="btn btn-ghost" data-action="import-json">⇧ Restaurar backup</button></div><p class="backup-note">Último backup: ${state.lastBackupAt?dateTime(state.lastBackupAt):'nunca'}</p></section><section class="settings-card"><h3>Exportar planilha CSV</h3><p>Gere um CSV para abrir no Excel, Google Sheets ou Power BI. Contém os campos principais de cada item, inclusive os arquivados.</p><div class="settings-actions"><button class="btn btn-ghost" data-action="backup-csv">⇩ Exportar CSV</button></div></section><section class="settings-card"><h3>Persistência do navegador</h3><p>Armazenamento ativo: <strong>${storageMode==='idb'?'IndexedDB (recomendado)':'localStorage (modo de compatibilidade)'}</strong>. Os dados ficam apenas neste dispositivo e perfil de navegador.</p><div class="settings-actions"><button class="btn btn-ghost" data-action="persist-storage">Solicitar armazenamento protegido</button></div><p class="backup-note" id="storageQuota">Estimativa de espaço: consultar ao clicar.</p></section><section class="settings-card"><h3>Projetos e arquivamento</h3><p>${active} projetos ativos, ${archived.length} arquivados. Arquivar não apaga tarefas nem histórico. Restaure um projeto para voltar a visualizar seus itens.</p><div class="settings-actions"><button class="btn btn-ghost" data-action="new-project">＋ Criar projeto</button></div>${archived.length?`<div class="line-divider"></div>${archived.map(p=>`<div class="task-line"><span class="project-dot" style="background:${p.color}"></span><div class="task-main"><strong>${esc(p.name)}</strong></div><button class="btn btn-muted" data-action="restore-project" data-id="${esc(p.id)}">Restaurar</button></div>`).join('')}`:''}</section><section class="settings-card"><h3>Interface e uso</h3><p>Alterne o tema, use <strong>N</strong> para novo item e <strong>Ctrl+K</strong> para pesquisar. Pode instalar o aplicativo como atalho no navegador.</p><button class="btn btn-ghost" data-action="toggle-theme">◐ Alternar tema claro/escuro</button></section><section class="settings-card"><h3>Privacidade e sincronização</h3><p>Nenhuma informação é enviada ao GitHub ou a serviços externos. O GitHub Actions publica somente os arquivos do aplicativo. Para outro dispositivo, exporte e importe o JSON. Abas deste mesmo site e navegador se atualizam automaticamente.</p><p class="backup-note">Formato de dados: v${state.version} · ${state.items.length} itens totais · ${state.activities.length} registros históricos</p></section></div>`;}
  function openProject(id=null){
    const p=id?findProject(id):null;currentProjectId=p?.id||null;
    $('#projectForm').reset();$('#projectModalTitle').textContent=p?'Editar projeto':'Novo projeto';
    $('#projectName').value=p?.name||'';$('#projectKey').value=p?.key||'';$('#projectColor').value=p?.color||'#2563eb';$('#projectDescription').value=p?.description||'';$('#projectRepo').value=p?.repository||'';
    $('#archiveProjectBtn').hidden=!p;$('#archiveProjectBtn').textContent=p?.archived?'Restaurar projeto':'Arquivar projeto';
    $('#projectDialog').showModal();$('#projectName').focus();
  }
  function openItem(id=null){
    const i=id?findItem(id):null;
    if(!i&&!state.projects.some(p=>!p.archived)){toast('Crie um projeto antes de cadastrar itens.','error');openProject();return;}
    currentItemId=i?.id||null;$('#itemForm').reset();
    $('#itemModalTitle').textContent=i?i.title:'Novo item';$('#itemModalEyebrow').textContent=i?keyOf(i):'ITEM DO BACKLOG';
    const form=$('#itemForm');const fields=['title','description','status','priority','type','startDate','dueDate','estimate','spent','sprint','assignee','link'];
    for(const field of fields){const control=form.elements.namedItem(field);if(control)control.value=i?.[field]??(field==='priority'?'medium':field==='type'?'feature':field==='status'?'backlog':'');}
    $('#itemProject').innerHTML=state.projects.filter(p=>!p.archived||i?.projectId===p.id).map(p=>`<option value="${esc(p.id)}">${esc(p.name)}${p.archived?' (arquivado)':''}</option>`).join('');
    $('#itemProject').value=i?.projectId||(prefs.projectId!=='all'?prefs.projectId:state.projects.find(p=>!p.archived)?.id);
    $('#itemLabels').value=i?.labels.join(', ')||'';
    $('#archiveItemBtn').hidden=!i;$('#archiveItemBtn').textContent=i?.archived?'Restaurar item':'Arquivar item';
    $('#newComment').value='';$('#newChecklistText').value='';renderItemExtras();
    $('#itemDialog').showModal();$('#itemTitle').focus();
  }
  function renderItemExtras(){
    const i=currentItemId?findItem(currentItemId):null;
    $('#saveFirstChecklist').textContent=i?'':'Salve o item antes de adicionar passos.';
    $('#saveFirstComment').textContent=i?'':'Salve o item antes de registrar atualizações.';
    $('#newChecklistText').disabled=!i;$('#addChecklistBtn').disabled=!i;$('#newComment').disabled=!i;$('#addCommentBtn').disabled=!i;
    $('#checklistCount').textContent=i?.checklist.length?`${i.checklist.filter(c=>c.done).length}/${i.checklist.length}`:'0 passos';
    $('#itemChecklist').innerHTML=i?.checklist.map(c=>`<label class="check-item ${c.done?'done':''}"><input type="checkbox" data-check-id="${esc(c.id)}" ${c.done?'checked':''}><span>${esc(c.text)}</span><button class="check-remove" type="button" data-remove-check="${esc(c.id)}" aria-label="Remover passo">×</button></label>`).join('')||'<div class="empty-inline">Ainda não há passos cadastrados.</div>';
    $('#itemComments').innerHTML=i?.comments.length?i.comments.slice().reverse().map(c=>`<div class="comment-entry"><p>${esc(c.text)}</p><small>${dateTime(c.createdAt)}</small></div>`).join(''):'<div class="empty-inline">Registre decisões e atualizações aqui.</div>';
    $('#itemHistory').innerHTML=i?state.activities.filter(a=>a.itemId===i.id).slice(0,100).map(a=>`<div class="history-entry"><strong>${esc(a.text)}</strong><small>${dateTime(a.time)}</small>${a.details.length?`<small>${a.details.map(d=>`${esc(d.field)}: ${esc(d.before)} → ${esc(d.after)}`).join(' · ')}</small>`:''}</div>`).join(''):'<div class="empty-inline">O histórico começa ao criar o item.</div>';
  }
  function formValue(form,name){return String(new FormData(form).get(name)||'').trim();}
  function ensureKey(name,id){let key=name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().split(/[^A-Z0-9]+/).filter(Boolean).slice(0,3).map(x=>x.slice(0,3)).join('').slice(0,7)||'PRJ';let counter=2,trial=key;while(state.projects.some(p=>p.id!==id&&p.key===trial)){trial=(key.slice(0,6)+counter++).slice(0,8);}return trial;}
  function submitProject(event){
    event.preventDefault();const f=event.currentTarget;
    const name=formValue(f,'name');let key=formValue(f,'key').toUpperCase().replace(/[^A-Z0-9-]/g,'').slice(0,8);
    if(!name){toast('Informe o nome do projeto.','error');return;}
    if(!key)key=ensureKey(name,currentProjectId);
    if(state.projects.some(p=>p.id!==currentProjectId&&p.key===key)){toast('Identificador já usado em outro projeto.','error');return;}
    const payload={name,key,color:formValue(f,'color'),description:formValue(f,'description'),repository:urlSafe(formValue(f,'repository'))};
    if(formValue(f,'repository')&&!payload.repository){toast('Link de repositório inválido.','error');return;}
    const id=currentProjectId||uid(),old=findProject(id);
    change(()=>{
      if(old){const changes=[];for(const [k,v]of Object.entries(payload))if(old[k]!==v){changes.push({field:k==='name'?'Nome':k==='description'?'Descrição':k,before:String(old[k]||''),after:String(v||'')});old[k]=v;}if(changes.length){old.updatedAt=now();activity('project_edit',`Projeto atualizado: ${name}`,id,null,changes);}else toast('Nenhuma alteração identificada.');}
      else {state.projects.push({id,...payload,archived:false,createdAt:now(),updatedAt:now()});activity('project_create',`Projeto criado: ${name}`,id);prefs.projectId=id;prefs.view='board';savePrefs();}
    });$('#projectDialog').close();toast(old?'Projeto atualizado.':'Projeto criado com sucesso.','success');
  }
  function submitItem(event){
    event.preventDefault();const f=event.currentTarget;const pId=formValue(f,'projectId');if(!findProject(pId)){toast('Escolha um projeto válido.','error');return;}
    const payload={projectId:pId,title:formValue(f,'title'),description:formValue(f,'description'),type:formValue(f,'type'),priority:formValue(f,'priority'),status:formValue(f,'status'),assignee:formValue(f,'assignee'),startDate:formValue(f,'startDate'),dueDate:formValue(f,'dueDate'),estimate:clampNum(formValue(f,'estimate')),spent:clampNum(formValue(f,'spent')),sprint:formValue(f,'sprint'),labels:[...new Set(formValue(f,'labels').split(',').map(x=>x.trim().slice(0,40)).filter(Boolean))].slice(0,20),link:urlSafe(formValue(f,'link'))};
    if(!payload.title){toast('Informe o título do item.','error');return;}
    if(payload.startDate&&payload.dueDate&&payload.dueDate<payload.startDate){toast('O prazo deve ser igual ou posterior à data de início.','error');return;}
    if(!STATUSES[payload.status]||!PRIORITIES[payload.priority]||!TYPES[payload.type]){toast('Valores de classificação inválidos.','error');return;}
    if(formValue(f,'link')&&!payload.link){toast('URL de referência inválida.','error');return;}
    const old=currentItemId?findItem(currentItemId):null;const id=old?.id||uid();
    change(()=>{
      if(old){const changes=[];for(const [k,v]of Object.entries(payload)){if(JSON.stringify(old[k])!==JSON.stringify(v)){const friendly=x=>k==='status'?STATUSES[x]:k==='priority'?PRIORITIES[x]:k==='type'?TYPES[x]:k==='projectId'?findProject(x)?.name:k==='labels'?x.join(', '):String(x??'');changes.push({field:fieldNames[k]||k,before:friendly(old[k]),after:friendly(v)});old[k]=v;}}
        if(changes.length){old.updatedAt=now();if(changes.some(c=>c.field==='Situação')){old.completedAt=old.status==='done'?now():null;activity('status',`${keyOf(old)} mudou de etapa para ${STATUSES[old.status]}`,old.projectId,old.id,changes.filter(c=>c.field==='Situação'));}const others=changes.filter(c=>c.field!=='Situação');if(others.length)activity('item_edit',`${keyOf(old)} atualizado: ${old.title}`,old.projectId,old.id,others);}else toast('Nenhuma alteração identificada.');
      }else {const number=1+Math.max(0,...state.items.filter(i=>i.projectId===pId).map(i=>i.number));const i={id,number,...payload,checklist:[],comments:[],archived:false,createdAt:now(),updatedAt:now(),completedAt:payload.status==='done'?now():null};state.items.push(i);activity('item_create',`${keyOf(i)} criado: ${i.title}`,pId,id);}
    });$('#itemDialog').close();toast(old?'Item atualizado.':'Item adicionado ao backlog.','success');
  }
  function moveItem(id,status){const i=findItem(id);if(!i||!STATUSES[status]||i.status===status||i.archived)return;change(()=>{const previous=i.status;i.status=status;i.updatedAt=now();i.completedAt=status==='done'?now():null;activity('status',`${keyOf(i)}: ${STATUSES[previous]} → ${STATUSES[status]}`,i.projectId,i.id,[{field:'Situação',before:STATUSES[previous],after:STATUSES[status]}]);});toast(`Movido para ${STATUSES[status]}.`,'success');}
  function addChecklist(){const text=$('#newChecklistText').value.trim();const i=currentItemId&&findItem(currentItemId);if(!i||!text)return;change(()=>{i.checklist.push({id:uid(),text,done:false});i.updatedAt=now();activity('checklist',`Passo adicionado a ${keyOf(i)}: ${text}`,i.projectId,i.id);});$('#newChecklistText').value='';renderItemExtras();}
  function toggleChecklist(id,done){const i=currentItemId&&findItem(currentItemId);const c=i?.checklist.find(x=>x.id===id);if(!c)return;change(()=>{c.done=done;i.updatedAt=now();activity('checklist',`${done?'Passo concluído':'Passo reaberto'} em ${keyOf(i)}: ${c.text}`,i.projectId,i.id);});renderItemExtras();}
  function removeChecklist(id){const i=currentItemId&&findItem(currentItemId);const c=i?.checklist.find(x=>x.id===id);if(!c)return;confirmAction(`Remover o passo “${c.text}”? A ação continuará registrada no histórico.`,()=>{change(()=>{i.checklist=i.checklist.filter(x=>x.id!==id);i.updatedAt=now();activity('checklist',`Passo removido de ${keyOf(i)}: ${c.text}`,i.projectId,i.id);});renderItemExtras();},true);}
  function addComment(){const text=$('#newComment').value.trim();const i=currentItemId&&findItem(currentItemId);if(!i||!text)return;change(()=>{i.comments.push({id:uid(),text,createdAt:now()});i.updatedAt=now();activity('comment',`Atualização registrada em ${keyOf(i)}: ${text.slice(0,180)}`,i.projectId,i.id);});$('#newComment').value='';renderItemExtras();toast('Atualização registrada no histórico.','success');}
  function archiveItem(){const i=currentItemId&&findItem(currentItemId);if(!i)return;const previous=i.archived;confirmAction(`${previous?'Restaurar':'Arquivar'} o item ${keyOf(i)}? ${previous?'Ele voltará ao backlog.':'O item e todo o seu histórico continuarão salvos.'}`,()=>{change(()=>{i.archived=!previous;i.updatedAt=now();activity('item_archive',`${keyOf(i)} ${previous?'restaurado':'arquivado'}`,i.projectId,i.id);});$('#itemDialog').close();toast(`Item ${previous?'restaurado':'arquivado'}.`,'success');},!previous);}
  function archiveProject(){const p=currentProjectId&&findProject(currentProjectId);if(!p)return;const was=p.archived;confirmAction(`${was?'Restaurar':'Arquivar'} o projeto ${p.name}? Todos os seus itens e histórico serão preservados.`,()=>{change(()=>{p.archived=!was;p.updatedAt=now();activity('project_archive',`Projeto ${was?'restaurado':'arquivado'}: ${p.name}`,p.id);if(!was&&prefs.projectId===p.id)prefs.projectId='all';savePrefs();});$('#projectDialog').close();toast(`Projeto ${was?'restaurado':'arquivado'}.`,'success');},!was);}
  function restoreProject(id){const p=findProject(id);if(!p||!p.archived)return;change(()=>{p.archived=false;p.updatedAt=now();activity('project_archive',`Projeto restaurado: ${p.name}`,p.id);});toast('Projeto restaurado.','success');}
  function confirmAction(message,onConfirm,danger=false){resolveConfirm=onConfirm;$('#confirmText').textContent=message;$('#confirmAccept').className='btn '+(danger?'btn-danger':'btn-primary');$('#confirmDialog').showModal();}
  function closeConfirm(doIt){const cb=resolveConfirm;resolveConfirm=null;$('#confirmDialog').close();if(doIt&&cb)cb();}
  function download(blob,filename){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
  function backupJson(){state.lastBackupAt=now();const content=JSON.stringify(state,null,2);download(new Blob([content],{type:'application/json;charset=utf-8'}),`backlog-studio-backup-${today()}.json`);save();render();toast('Backup completo exportado. Guarde o arquivo em local seguro.','success');}
  function backupCsv(){const columns=['Código','Projeto','Título','Descrição','Tipo','Prioridade','Status','Responsável','Início','Prazo','Estimativa horas','Horas gastas','Sprint','Etiquetas','URL','Arquivado','Criado em','Atualizado em','Concluído em','Checklist concluído','Total checklist','Comentários'];const encode=v=>{let t=String(v??'');if(/^[\s]*[=+@\-]/.test(t)&&!/^\d{4}-\d{2}-\d{2}$/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"';};const lines=[columns,...state.items.map(i=>[keyOf(i),findProject(i.projectId)?.name||'',i.title,i.description,TYPES[i.type],PRIORITIES[i.priority],STATUSES[i.status],i.assignee,i.startDate,i.dueDate,i.estimate,i.spent,i.sprint,i.labels.join(', '),i.link,i.archived?'sim':'não',dateTime(i.createdAt),dateTime(i.updatedAt),i.completedAt?dateTime(i.completedAt):'',i.checklist.filter(c=>c.done).length,i.checklist.length,i.comments.length])].map(row=>row.map(encode).join(';')).join('\r\n');download(new Blob(['\ufeff'+lines],{type:'text/csv;charset=utf-8'}),`backlog-studio-itens-${today()}.csv`);toast('Planilha CSV exportada.','success');}
  async function importJson(file){if(!file)return;if(file.size>25*1024*1024){toast('Arquivo acima do limite de 25 MB.','error');return;}let parsed;try{parsed=normalizeState(JSON.parse(await file.text()));}catch(e){toast('Não foi possível ler backup: '+e.message,'error');return;}
    confirmAction(`Restaurar ${parsed.projects.length} projetos, ${parsed.items.length} itens e ${parsed.activities.length} eventos? Os dados atuais serão substituídos. Antes disso, um backup automático será baixado.`,()=>{if(state.projects.length||state.items.length)backupJson();state=parsed;activity('import','Backup importado e restaurado');prefs={...defaultPrefs,theme:prefs.theme};savePrefs();change(()=>{});toast('Backup restaurado com sucesso.','success');},true);
  }
  async function persistStorage(){try{if(!navigator.storage){toast('Navegador sem API de armazenamento protegido.','error');return;}const granted=await navigator.storage.persist();const estimate=await navigator.storage.estimate();const used=(estimate.usage||0)/1024/1024;const quota=(estimate.quota||0)/1024/1024;const label=`Uso: ${used.toFixed(2)} MB de ${quota.toFixed(0)} MB disponíveis · Protegido: ${granted?'sim':'não'}`;const el=$('#storageQuota');if(el)el.textContent=label;toast(granted?'Proteção de armazenamento concedida.':'Navegador não concedeu proteção. Continue exportando backups.',granted?'success':'error');}catch(e){toast('Não foi possível consultar armazenamento: '+e.message,'error');}}
  function switchTheme(){prefs.theme=prefs.theme==='light'?'dark':'light';savePrefs();render();}
  function navigate(view){prefs.view=view;prefs.search='';prefs.showArchived=false;savePrefs();render();$('#sidebar').classList.remove('open');$('#mobileBackdrop').hidden=true;window.scrollTo({top:0,behavior:'instant'});}
  function selectProject(id){prefs.projectId=id;prefs.view='board';prefs.search='';savePrefs();render();$('#sidebar').classList.remove('open');$('#mobileBackdrop').hidden=true;}
  function toast(message,type=''){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;$('#toastRegion').append(el);setTimeout(()=>el.remove(),4800);}
  function installHandlers(){
    document.addEventListener('click',event=>{
      const close=event.target.closest('.close-dialog');if(close){close.closest('dialog').close();return;}
      const elem=event.target.closest('[data-action]');if(!elem)return;
      const {action,id,view}=elem.dataset;
      if(action==='new-project')openProject();else if(action==='new-item')openItem();else if(action==='edit-item')openItem(id);else if(action==='edit-project')openProject(id);
      else if(action==='navigate')navigate(view);else if(action==='select-project')selectProject(id);
      else if(action==='backup-json')backupJson();else if(action==='backup-csv')backupCsv();else if(action==='import-json')$('#importInput').click();else if(action==='persist-storage')persistStorage();else if(action==='toggle-theme')switchTheme();else if(action==='restore-project')restoreProject(id);
      else if(action==='month-prev'){prefs.calendarOffset--;render();}else if(action==='month-next'){prefs.calendarOffset++;render();}else if(action==='month-today'){prefs.calendarOffset=0;render();}
    });
    document.addEventListener('keydown',event=>{
      if((event.key==='Enter'||event.key===' ')&&event.target.matches('[data-action][tabindex="0"]')){event.preventDefault();event.target.click();return;}
      if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(!['board','list','calendar'].includes(prefs.view))navigate('list');$('#searchInput')?.focus();return;}
      if(event.key.toLowerCase()==='n'&&!event.ctrlKey&&!event.metaKey&&!event.altKey&&!['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName)&&!document.querySelector('dialog[open]')){event.preventDefault();openItem();}
    });
    $('#main').addEventListener('input',event=>{if(event.target.id==='searchInput'){const caret=event.target.selectionStart;prefs.search=event.target.value;render();const el=$('#searchInput');el?.focus();if(el&&caret!==null)el.setSelectionRange(caret,caret);}});
    $('#main').addEventListener('change',event=>{const t=event.target;const mapping={projectFilter:'projectId',priorityFilter:'priority',typeFilter:'type',statusFilter:'status',sortFilter:'sort'};if(mapping[t.id]){prefs[mapping[t.id]]=t.value;savePrefs();render();}else if(t.id==='showArchived'){prefs.showArchived=t.checked;savePrefs();render();}});
    let dragId=null;
    $('#main').addEventListener('dragstart',e=>{const card=e.target.closest('[data-drag-id]');if(!card)return;dragId=card.dataset.dragId;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragId);card.classList.add('dragging');});
    $('#main').addEventListener('dragend',e=>{e.target.closest('[data-drag-id]')?.classList.remove('dragging');$$('.board-column').forEach(c=>c.classList.remove('drag-over'));dragId=null;});
    $('#main').addEventListener('dragover',e=>{const col=e.target.closest('[data-drop-status]');if(!col)return;e.preventDefault();e.dataTransfer.dropEffect='move';$$('.board-column').forEach(c=>c.classList.toggle('drag-over',c===col));});
    $('#main').addEventListener('drop',e=>{const col=e.target.closest('[data-drop-status]');if(!col)return;e.preventDefault();const id=dragId||e.dataTransfer.getData('text/plain');dragId=null;if(id)moveItem(id,col.dataset.dropStatus);});
    $('#projectForm').addEventListener('submit',submitProject);$('#itemForm').addEventListener('submit',submitItem);
    $('#archiveProjectBtn').addEventListener('click',archiveProject);$('#archiveItemBtn').addEventListener('click',archiveItem);
    $('#addChecklistBtn').addEventListener('click',addChecklist);$('#newChecklistText').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();addChecklist();}});
    $('#itemChecklist').addEventListener('change',e=>{if(e.target.matches('[data-check-id]'))toggleChecklist(e.target.dataset.checkId,e.target.checked);});
    $('#itemChecklist').addEventListener('click',e=>{const b=e.target.closest('[data-remove-check]');if(b){e.preventDefault();removeChecklist(b.dataset.removeCheck);}});
    $('#addCommentBtn').addEventListener('click',addComment);
    $('#confirmAccept').addEventListener('click',()=>closeConfirm(true));$('#confirmCancel').addEventListener('click',()=>closeConfirm(false));
    $('#confirmDialog').addEventListener('close',()=>{resolveConfirm=null;});
    $('#backupTop').addEventListener('click',backupJson);$('#themeToggle').addEventListener('click',switchTheme);$('#sidebarAddProject').addEventListener('click',()=>openProject());
    $('#menuToggle').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#mobileBackdrop').hidden=false;});
    $('#mobileBackdrop').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#mobileBackdrop').hidden=true;});
    $('#importInput').addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';if(file)await importJson(file);});
    document.querySelectorAll('dialog').forEach(dialog=>{dialog.addEventListener('click',e=>{if(e.target===dialog&&dialog!==$('#confirmDialog'))dialog.close();});});
  }
  async function receiveChange(){try{await saveQueue;const raw=storageMode==='idb'?await getFromIdb():JSON.parse(localStorage.getItem(LS_DATA)||'null');if(raw&&raw.revision!==state.revision){state=normalizeState(raw);render();toast('Dados atualizados por outra aba.');}}catch(e){console.warn('Sincronização entre abas falhou',e);}}
  async function init(){
    try{const prefRaw=localStorage.getItem(LS_PREFS);if(prefRaw){const saved=JSON.parse(prefRaw);prefs={...defaultPrefs,...saved,search:''};if(!['light','dark'].includes(prefs.theme))prefs.theme='light';}}catch{}
    try{db=await openDb();const saved=await getFromIdb();if(saved)state=normalizeState(saved);else if(localStorage.getItem(LS_DATA))state=normalizeState(JSON.parse(localStorage.getItem(LS_DATA)));}
    catch(error){storageMode='localStorage';try{const saved=localStorage.getItem(LS_DATA);if(saved)state=normalizeState(JSON.parse(saved));}catch(e){console.error('Erro de recuperação',e);toast('Não foi possível carregar dados locais. Faça uma restauração JSON.','error');}toast('IndexedDB indisponível: usando armazenamento local de compatibilidade.','error');}
    installHandlers();render();
    if('BroadcastChannel' in window){channel=new BroadcastChannel(CHANNEL);channel.onmessage=receiveChange;}
    window.addEventListener('storage',e=>{if(e.key==='backlog-studio-ping'||e.key===LS_DATA)receiveChange();});
    if('serviceWorker' in navigator&&location.protocol==='https:'){navigator.serviceWorker.register('./sw.js').catch(error=>console.warn('PWA offline não habilitado',error));}
    window.addEventListener('beforeunload',e=>{if(isSaving){e.preventDefault();}});
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
  // Interface de diagnóstico para testes automatizados, sem expor a alteração de estado.
  window.BacklogStudio={getStats:()=>({projects:state.projects.length,items:state.items.length,activities:state.activities.length,storageMode}),getState:()=>structuredClone(state)};
})();
